  node.onsubmit=event=>{if(event.target.matches('[data-ps-catalog-filter]')){event.preventDefault();readFilters();resetList('products');void run(()=>fillList('products',0,listPages.get(listKey('products'))?.size||'20'));return;}if(event.target.matches('[data-ps-flow-form]')){event.preventDefault();const data=new FormData(event.target);void run(async()=>{const f={id:crypto.randomUUID(),store,...Object.fromEntries(data)};flows=flowStorage().write([...flowStorage().read(),f]);status='Flujo guardado para tu cuenta en este navegador.';});return;}if(event.target.matches('[data-ps-receipt-search]')){event.preventDefault();receiptQuery=root.querySelector('[data-ps-receipt-query]')?.value||'';render();return;}if(event.target.matches('[data-ps-query-search]')){event.preventDefault();recipeSearch=root.querySelector('[data-ps-query-name]')?.value||'';render();return;}if(!event.target.matches('[data-ps-search]'))return;event.preventDefault();readFilters();resetList('orders');void run(async()=>{if(tab==='orders'){await read('orders');await fillList('orders',0,listPages.get(listKey('orders'))?.size||'20');}else await scan('orders');});};
  node.onchange=event=>{if(event.target.hasAttribute('data-ps-page-size')){readFilters();const resource=event.target.dataset.psPageSize,size=event.target.value;listPages.set(listKey(resource),{size,page:0});if(['orders','products'].includes(resource))void run(()=>fillList(resource,0,size));else render();return;}const payments=event.target.closest('[data-ps-payment-filter]');if(payments){const count=payments.querySelectorAll('input:checked').length;payments.querySelector('summary').textContent='Medios de pago · '+(count?count+' seleccionados':'Todos');}if(event.target.hasAttribute('data-ps-column')){readFilters();columns[event.target.dataset.psColumn]=event.target.checked;render();}if(event.target.hasAttribute('data-ps-density')){readFilters();density=event.target.value;render();}};
  node.onclick=event=>{
   const b=event.target.closest('[data-prestashop-action]');if(!b||!active())return;if(b.dataset.prestashopAction==='stop'){stopRequested=true;status='Deteniendo tras la lectura actual…';return;}if(busy)return;readFilters();const a=b.dataset.prestashopAction;
   if(a==='catalog-quality'){catalogMode='quality';recipe='';render();return;}if(a==='rotation'){catalogMode='rotation';tab='catalog';render();void run(async()=>{if(!get('orders')||get('orders').possibly_more)await scan('orders');if(stopRequested||!active())return;if(!get('products')||get('products').possibly_more)await scan('products');if(stopRequested||!active())return;if(!get('stock_availables')||get('stock_availables').possibly_more)await scan('stock_availables');});return;}
   if(a==='today'||a==='week'){filter=initialFilter();if(a==='week'){const d=new Date(filter.from+'T12:00:00');d.setDate(d.getDate()-6);filter.from=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}void run(()=>scan('orders'));return;}
   if(a==='flow-copy'||a==='flow-remove'||a==='flow-run'){const f=flows.find(f=>f.id===b.dataset.flow);if(!f)return;void run(async()=>{if(a==='flow-copy'){flows=flowStorage().write([...flows,{...f,id:crypto.randomUUID(),name:f.name.slice(0,93)+' · copia'}]);return;}if(a==='flow-remove'){if(flowRemove!==f.id){flowRemove=f.id;return;}flows=flowStorage().write(flows.filter(row=>row.id!==f.id));flowRemove=null;return;}const q=PRESTASHOP_QUERY_RECIPES.find(q=>q.id===f.recipe&&q.target);store=f.store;if(!ready()){tab='connection';throw Error('Verifica la conexión de '+store+' antes de ejecutar el flujo.');}filter={...initialFilter(),...prestashopFlowRange(f,isoToday())};recipe=f.recipe;tab=q.target;catalogMode='quality';for(const resource of q.resources||[q.target==='orders'?'orders':'products']){if(!active()||stopRequested)return;await scan(resource);}status='Flujo '+f.name+' ejecutado · '+status;});return;}if(a==='receipts-open'){void run(()=>onReceipts({store,id:b.dataset.receipt||null}));return;}if(a==='receipts-refresh'){void run(refreshReceipts);return;}if(a==='tab'){if(!availableTabs().some(([key])=>key===b.dataset.tab))return;tab=b.dataset.tab;render();if(tab==='receipts')void run(refreshReceipts);if(tab==='saved_queries')void run(async()=>{flows=flowStorage().read();});return;}if(a==='store'){catalogFilter={query:'',category:'all',active:'all'};store=b.dataset.store;status='Tienda seleccionada: '+store+'.';render();if(tab==='receipts')void run(refreshReceipts);else if(autoload&&ready()&&!get('orders'))void run(()=>scan('orders'));return;}
   if(a==='recipe-group'){recipeGroup=b.dataset.group;recipeSearch=root.querySelector('[data-ps-query-name]')?.value||'';render();return;}if(a==='recipe-needs'){const q=PRESTASHOP_QUERY_RECIPES.find(q=>q.id===b.dataset.recipe);tab='connection';status=q?.needs||'Comprueba los recursos disponibles.';render();return;}
   if(a==='clear-recipe'){recipe='';render();return;}if(a==='recipe'){const q=PRESTASHOP_QUERY_RECIPES.find(x=>x.id===b.dataset.recipe);if(!q?.target)return;catalogMode='quality';recipe=q.id;tab=q.target;if(q.target==='orders'){filter.daily=true;filter.start='20:00';filter.end='20:30';results.delete(key('orders'));render();}else{render();void run(async()=>{for(const resource of q.resources||['products']){if(!active()||stopRequested)return;if(!get(resource)||get(resource).possibly_more)await scan(resource);}});}return;}if(a==='list-page'){const resource=b.dataset.resource,preferences={...(listPages.get(listKey(resource))||{}),page:Number(b.dataset.page)};if(['orders','products'].includes(resource))void run(async()=>{await fillList(resource,preferences.page,preferences.size||'20');if(active())listPages.set(listKey(resource),preferences);});else{listPages.set(listKey(resource),preferences);render();}return;}if(a==='catalog-reset'){catalogFilter={query:'',category:'all',active:'all'};resetList('products');render();return;}if(a==='all-payments'){filter.payment=[];resetList('orders');render();return;}if(a==='filter'){resetList('orders');void run(()=>fillList('orders',0,listPages.get(listKey('orders'))?.size||'20'));return;}if(a==='open-apis'){onManage();return;}if(a==='module'){onModule?.();return;}if(a==='billing'){onBilling();return;}
   if(a==='invoice'){const row=get('orders')?.rows.find(r=>String(r.id)===b.dataset.id);if(!row)return;const reference=ticketSourceKey(store,row);void run(async()=>{let detail=details.get(store+'|'+connection()?.id+'|'+connection()?.revision+'|'+row.id);if(!detail){await read('order_details',false,String(row.id));detail=details.get(store+'|'+connection()?.id+'|'+connection()?.revision+'|'+row.id);}while(active()&&detail?.possibly_more){await read('order_details',true,String(row.id));detail=details.get(store+'|'+connection()?.id+'|'+connection()?.revision+'|'+row.id);}if(active())await onBilling({store,order:row,reference,detail});});return;}
   if(a==='export'){const r=get(b.dataset.resource);if(!r)return;const fields=PRESTASHOP_RESOURCES[b.dataset.resource];download(new Blob(['\ufeff'+csv(r.rows,fields.map(f=>({label:labels[f]||f,get:row=>row[f]})))],{type:'text/csv;charset=utf-8'}),'prestashop-'+store+'-'+b.dataset.resource+'-'+isoToday()+'.csv');return;}
   void run(async()=>{if(a==='discover'){const c=connection(),shop=store;const r=await invoke({action:'prestashop_discover',store:shop,id:c.id,revision:c.revision,call_id:crypto.randomUUID()});if(!active()||shop!==store)return;if(!r?.ok||r.store!==shop||!Array.isArray(r.resources)||!Array.isArray(r.tpv_resources))throw Error('Diagnóstico de recursos no verificable.');capabilities.set(shop+'|'+c.id+'|'+c.revision,r);status='Recursos y disponibilidad TPV comprobados en '+shop+'.';}else if(a==='refresh')await refresh();else if(a==='read'){resetList(b.dataset.resource);if(b.dataset.resource==='products')await read('products');else await scan(b.dataset.resource);if(b.dataset.resource==='products'&&active()&&!get('categories')){const success=status;try{await scan('categories');status=success;}catch(e){status=success+' No se pudieron leer los nombres de categorías; se muestran sus identificadores.';}}}else if(a==='more')await read(b.dataset.resource,true);else if(a==='detail'||a==='detail-more')await read('order_details',a==='detail-more',b.dataset.id);});
  };
  if(receiptsOnly())tab='receipts';render();
